import rawTiming from "./data/timing.json";
import rawDeck from "./data/slides.json";
import rawMusic from "./data/music.json";
import type { SpeakerId } from "./data/speakers";

// timing.json is generated by scripts/align.mjs, so its shape is declared here
// rather than inferred. Inference would quietly follow a change in the
// generator instead of failing the typecheck.

export type SlideCue = {
  /** Two-digit deck label, e.g. "03". */
  slide: string;
  label: string;
  falaId: string;
  speaker: SpeakerId;
  start: number;
  end: number;
  startFrame: number;
  endFrame: number;
  durationInFrames: number;
  /** Index into deck.slides. -1 means the map points at a slide the deck lost. */
  deckIndex: number;
};

export type SpeakerTurn = {
  speaker: SpeakerId;
  start: number;
  end: number;
  startFrame: number;
  endFrame: number;
};

export type RevealCue = {
  /** Matches a `data-reveal` attribute in the extracted slide markup. */
  id: string;
  slide: string;
  start: number;
  startFrame: number;
  /** How the time was resolved: an anchor phrase, or an offset. For debugging. */
  source: string;
  /** True when the slide's own window forced the time to move. */
  clamped: boolean;
};

export type Timing = {
  fps: number;
  /** Narration plus the outro tail; this is the video length. */
  durationSec: number;
  /** Where the audio itself ends. */
  narrationSec: number;
  durationInFrames: number;
  /** Share of roteiro words Whisper confirmed. Below ~0.8, review the cues. */
  alignmentRate: number;
  turns: SpeakerTurn[];
  slides: SlideCue[];
  reveals: RevealCue[];
};

export type DeckSection = {
  id: string;
  label: string;
  screenLabel: string;
  speakerNotes: string;
  style: string;
  html: string;
};

export type Deck = {
  globalCss: string;
  slides: DeckSection[];
};

/**
 * Volume automation for the music bed, from scripts/music-bed.mjs. The track is
 * shorter than the video, so it is laid down twice: `first` from frame zero,
 * `second` taking over at `seamFrame` and indexed from there.
 */
export type MusicBed = {
  file: string;
  fps: number;
  /** Decibels the bed sits under whoever is speaking. */
  headroomDb: number;
  seamFrame: number;
  /** Frames trimmed off the front of the track for the second pass. */
  secondPassTrimFrames: number;
  /** Per-frame gain for the first pass, from composition frame 0. */
  first: number[];
  /** Per-frame gain for the second pass, from `seamFrame`. */
  second: number[];
};

export const timing = rawTiming as Timing;
export const deck = rawDeck as Deck;
export const music = rawMusic as MusicBed;
